// js
const item = first(ctx.reads.leave_catalog);
if (item == null || !ctx.lookup.no_pay.includes(item.code)) return true;
const employer = ctx.subject.employer;
const cutoff = Number(get(employer, 'pay_cutoff_day', 1));
const halves = get(employer, 'payment_schedule.frequency', 'MONTHLY') === 'SEMI_MONTHLY';
const shifted = (month, by) => add_months(month + '-01', by).slice(0, 7);
const periodOf = (date) => {
	const month = date.slice(0, 7);
	const dayOf = Number(date.slice(8, 10));
	const part = dayOf <= 15 ? 1 : 2;
	if (!halves) return cutoff > 1 && dayOf >= cutoff ? shifted(month, 1) : month;
	if (cutoff <= 1) return month + '-' + part;
	return part === 1 ? month + '-2' : shifted(month, 1) + '-1';
};
const dates = ctx.entry.days.map((day) => day.date);
if (get(ctx.entry, 'is_reversal', false) === true && ctx.reads.leave_catalog_entry.some((row) => row.days.some((day) => dates.includes(day.date))))
	throw 'That day has not been paid yet. Delete the entry instead of reversing it.';
const ran = ctx.reads.payroll_run.map((run) => run.period);
const closed = ctx.entry.days.find((day) => ran.includes(periodOf(day.date)));
if (closed != null)
	throw closed.date + ' is in a period that has already run. Date this entry in the next period to run, and that run takes it.';
return true;

// js
// Employment Act s.89(1): the 60 days of hospitalisation leave include the 14 days of outpatient sick leave.
const shared = ctx.reads.leave_catalog;
const item = shared.find((row) => row.id === ctx.entry.catalog_id);
if (item == null) return true;
const year = String(ctx.entry.days[0].date).slice(0, 4);
const ids = shared.map((row) => row.id);
const within = (days) => days.filter((day) => String(day.date).slice(0, 4) === year).length / 2;
const taken = ctx.reads.leave_catalog_entry
	.filter((row) => ids.includes(row.catalog_id))
	.reduce((total, row) => total + (get(row, 'is_reversal', false) === true ? -1 : 1) * within(row.days), 0);
const wanted = get(ctx.entry, 'is_reversal', false) === true ? 0 : within(ctx.entry.days);
const hospital = shared.find((row) => row.code === ctx.lookup.hospitalisation);
const months = calendar_completed_months(String(ctx.subject.employment.effective_range.from), String(ctx.entry.days[0].date));
const cap = get(hospital.lookup, 'service_bands', []).filter((band) => band.service_months <= months).reduce((best, band) => Math.max(best, band.days), 0);
if (taken + wanted > cap) throw 'Sick and hospitalisation leave together would pass the ' + cap + ' days the year allows.';
return true;

// js
const item = first(ctx.reads.workplace_case_catalog);
if (get(item, 'lookup.grants', null) == null) return true;
if (get(ctx.entry, 'inputs.employment_id', null) == null) throw 'Choose the employee this case is for.';
const decision = get(ctx.entry, 'inputs.decision', '');
if (!['', 'CONFIRMED', 'REJECTED'].includes(decision)) throw 'A case is confirmed or rejected.';
if (get(ctx.entry, 'inputs.is_reversal', false) === true) {
	const account = get(first(ctx.reads.employee_balance), 'account', {});
	const done = get(account, 'leave_case', {});
	const original = get(ctx.entry, 'inputs.reverses', '');
	if (!Object.hasOwn(done, original)) throw 'Only a confirmed case can be reversed.';
	if (Object.hasOwn(done, 'reversed.' + original)) throw 'This case has already been reversed.';
	const leave = get(account, 'leave', {});
	const short = get(item, 'lookup.grants', []).filter((grant) => {
		const key = original + '.' + grant.code;
		const given = Object.hasOwn(done, key) ? Number(done[key]) : 0;
		return given > 0 && Number(Object.hasOwn(leave, grant.code) ? leave[grant.code] : 0) < given;
	});
	if (short.length > 0) throw 'Reverse the leave already taken first: ' + short[0].code + ' has fewer days left than this case gave.';
	return true;
}
if (decision === 'CONFIRMED' && get(item, 'lookup.certificate', false) === true && get(ctx.entry, 'evidence_file', null) == null)
	throw 'Attach the certificate before confirming this case.';
return true;
